def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 2:
        return 'C'
    # Count opponent defections and patterns
    opp_defects = 0
    opp_coops = 0
    for h in history:
        if h[1] == 'D':
            opp_defects += 1
        else:
            opp_coops += 1
    my_defects = 0
    my_coops = 0
    for h in history:
        if h[0] == 'D':
            my_defects += 1
        else:
            my_coops += 1

    # If opponent has never defected, cooperate
    if opp_defects == 0:
        return 'C'

    # If opponent started defecting early and often, defect
    # Early defection detection
    if n >= 3:
        early_defects = sum(1 for h in history[:3] if h[1] == 'D')
        if early_defects >= 2:
            return 'D'

    # Tit-for-tat with forgiveness when opponent is mostly cooperative
    opp_defect_rate = opp_defects / n

    # If opponent cooperates more than 80% of the time, cooperate
    if opp_defect_rate <= 0.2:
        # But if last round opponent defected and we cooperated, defect once
        if history[-1][1] == 'D' and history[-1][0] == 'C':
            return 'D'
        return 'C'

    # If opponent cooperates more than 60% but we're being exploited
    if opp_defect_rate <= 0.4:
        # Punish if last round was defection against our cooperation
        if history[-1][1] == 'D':
            return 'D'
        # Check if we're being exploited: opponent defects after we cooperate
        exploit_count = 0
        for i in range(1, n):
            if history[i][1] == 'D' and history[i-1][0] == 'C':
                exploit_count += 1
        if exploit_count > n * 0.3:
            return 'D'
        return 'C'

    # If opponent defects a lot, defect most of the time
    if opp_defect_rate > 0.6:
        # Occasionally cooperate to test (with low probability)
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Middle ground: generous tit-for-tat
    if history[-1][1] == 'D':
        # Forgive occasionally if opponent hasn't been too bad
        if opp_defect_rate < 0.5 and rng.random() < 0.3:
            return 'C'
        return 'D'
    return 'C'
